import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"11、【泰】 乾下坤上","description":"周易口诀义 - 11、【泰】 乾下坤上","frontmatter":{"title":"11、【泰】 乾下坤上","description":"周易口诀义 - 11、【泰】 乾下坤上"},"headers":[],"relativePath":"zh/classics/koujueyi/013.md","filePath":"zh/classics/koujueyi/013.md"}'),r={name:"zh/classics/koujueyi/013.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_11、【泰】-乾下坤上" tabindex="-1">11、【泰】 乾下坤上 <a class="header-anchor" href="#_11、【泰】-乾下坤上" aria-label="Permalink to “11、【泰】 乾下坤上”">​</a></h1><p>彖曰：「泰，小往大来，吉，亨」。则是天地交而万物通也，上下交而其志同也。内阳而外阴，内健而外顺，内君子而外小人，君子道长，小人道消也。</p><p>象曰：天地交，泰，后以财成天地之道，辅相天地之宜，以左右民。</p><p>初九，拔茅茹以其汇，征吉。</p><p>象曰：「拔茅征吉」，志在外也。</p><p>九二，包荒，用冯河，不遐遗，朋亡，得尚于中行。</p><p>象曰：「包荒得尚于中行」，以光大也。</p><p>九三，无平不陂，无往不复，艰贞无咎。勿恤其孚，于食有福。</p><p>象曰：「无往不复」，天地际也。</p><p>六四，翩翩，不富以其邻，不戒以孚。</p><p>象曰：「翩翩不富」，皆失实也。「不戒以孚」，中心愿也。</p><p>六五，帝乙归妹，以祉元吉。</p><p>象曰：「以祉元吉」，中以行愿也。</p><p>上六，城复于隍，勿用师，自邑告命，贞吝。</p><p>象曰：「城复于隍」，其命乱也。</p><p>解读</p><p>泰，小往大来，吉亨者，泰是通泰之名，以天地交感，万物长育，故名「泰」也。阴气消，故曰「小往」；阳气长，故曰「大来」。以天地通泰，君子道长，小人道消，以此吉而亨通矣，故曰「吉亨」也。象曰「天地交，泰」者，天气降下，地气腾上，上下交感，万物资育，故是通泰之象也。「后以财成天地之道，辅相天地之宜，以左右民」者，后，君。财，裁也，剪也。道不失其宜，即是春生秋杀，各有宜也。相，助也，谓助天地所宜之物，五土所生，各以其时也。左右者，助也，谓左右群臣助君之化也。裁成天地发育所生之宜。欲明通泰之时，助天地之化，非南面之君，不可以施其化成天地之功也。</p><p>初九，拔茅茹以其汇，征吉。茹，相牵引之貌也。夫通泰之道，天气下降，地气上腾，三阳皆欲上升。初为三阳之首，若行则众类从之，犹似拔其茅根，以相连茹，以其三阳之类，阴不敢拒，所以征进而获吉矣。</p><p>九二，包荒，用冯河，不遐遗。「朋亡，得尚于中行」者，包，含也。荒，秽也。冯河，是无舟渡水，冯陵于河，此顽愚之人也。言九二以刚取中，心又通泰，即物无不纳，虽复荒秽之物，顽愚之人，悉皆包含，不计遐远，无所弃遗，故曰「包荒，用冯河，不遐遗也」。心既弘大，无偏无党，即不私于朋友，天下皆悉纳之，故曰「朋亡」也。亡，无也，谓无私于朋友。「得尚乎中行」者，尚，配也；中行，君也。此九二既备众德，无物不纳，即可以配于君位，下治天下也。</p><p>「九三，无平不陂，无往不复，艰贞无咎。勿恤其孚，于食有福」者，陂，险陷也；复，反也；九三处天地之际，当通泰之时，天气降下，地气腾上，今泰道将极，否道却至，即天气上升，地气下复，犹似平路，必致崩陷，如暂往必有反复，故曰「无平不陂，无往不复」也。时既变革，必致危殆，当须艰固其志，守正不回，乃得无咎，故曰「艰贞无咎」。众皆同志，已去即从，故不须忧恤，而同其信，故曰「勿恤其孚」。诚信既施，德泽归矣，自获福庆，故曰「于食有福」。</p><p>「六四，翩翩，不富以其邻，不戒以孚」者，翩翩者，飞动之貌也；六四处坤之首，众阴皆随之，故六四翩翩飞动归于下，故曰「翩翩」。泰道既极，坤复其体，众皆志愿同归于下，六四若行，五之与上皆相随从，故六五、上六不待六四与之财相诱，故曰「不富以其邻」也。邻皆愿下而不待赒赡，众愿同行，故不假戒告而自孚信，故曰「不戒以孚」也。</p><p>六五：帝乙归妹，以祉元吉，「归妹」犹言嫁妹也。以五贵位，降德就二，犹似帝王嫁妹于二，故曰「帝乙归妹」也。处通泰之时，天地交好，以帝王之妹降于庶人，得配匹之宜，尽通泰之道，故获祉福而得大吉也，故曰「以祉元吉」。祉，福也。</p><p>上六：城复于隍，勿用师，自邑告命，贞吝者，隍，城堑也。处通泰之时，上下相扶，君臣和顺，犹似当初以土相培而就其城。今泰道已极，否道至，即是城之崩倒，却至于堑，故曰「城复于隍」也。否道既至，教令不行，故不烦用师。假使归其己邑，告戒令命，亦皆不从，是正之贱矣，故曰「勿用师，自邑告命，贞吝」也。</p>',23)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
